function linearize(channel) {
  const c = channel / 255;
  return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
}

function passesAAText(ratio, isLarge) {
  const needed = isLarge ? 3 : 4.5;
  return ratio >= needed;
}

function ratioFromLuminance(a, b) {
  const lighter = Math.max(a, b);
  const darker = Math.min(a, b);
  return Math.round(((lighter + 0.05) / (darker + 0.05)) * 100) / 100;
}

function wcagBand(ratio) {
  if (ratio >= 7) return "AAA";
  if (ratio >= 4.5) return "AA";
  return "fail";
}

function grayOnWhite(gray) {
  const c = gray / 255;
  const lin = c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
  const ratio = 1.05 / (lin + 0.05);
  return Math.round(ratio * 100) / 100;
}

function contrast(fg, bg) {
  const lum = ([r, g, b]) => {
    const lin = (v) => {
      const c = v / 255;
      return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
    };
    return 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b);
  };
  const a = lum(fg);
  const b = lum(bg);
  const ratio = (Math.max(a, b) + 0.05) / (Math.min(a, b) + 0.05);
  return Math.round(ratio * 100) / 100;
}

function lightestPassingGray(minRatio) {
  let best = -1;
  for (let gray = 0; gray <= 255; gray++) {
    const c = gray / 255;
    const lin = c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
    if (1.05 / (lin + 0.05) >= minRatio) best = gray;
  }
  return best;
}
